create table profiles(id uuid primary key references auth.users on delete cascade, name text, created_at timestamptz default now());
create table characters(id text primary key, name text not null, avatar text, bio text, personality text not null, greeting text, tags text[] default '{}', voice_id text, creator_id uuid default auth.uid() references auth.users on delete set null, created_at timestamptz default now());
create table char_stats(character_id text primary key, chat_count bigint default 0);
create table follows(user_id uuid default auth.uid() references auth.users on delete cascade, character_id text, primary key(user_id,character_id));
create table chats(id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users on delete cascade, character_id text not null, created_at timestamptz default now(), unique(user_id,character_id));
create table messages(id bigserial primary key, chat_id uuid references chats(id) on delete cascade, role text check (role in ('user','assistant')), content text, image_url text, created_at timestamptz default now());
alter table profiles enable row level security; alter table characters enable row level security; alter table char_stats enable row level security; alter table follows enable row level security; alter table chats enable row level security; alter table messages enable row level security;
create policy "own profile" on profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "read characters" on characters for select using (true);
create policy "insert own characters" on characters for insert with check (creator_id=auth.uid());
create policy "edit own characters" on characters for update using (creator_id=auth.uid());
create policy "delete own characters" on characters for delete using (creator_id=auth.uid());
create policy "read stats" on char_stats for select using (true);
create policy "own follows" on follows for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own chats" on chats for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own messages" on messages for all using (exists(select 1 from chats c where c.id=chat_id and c.user_id=auth.uid())) with check (exists(select 1 from chats c where c.id=chat_id and c.user_id=auth.uid()));
create function bump_chat(cid text) returns void language sql security definer set search_path=public as $$ insert into char_stats(character_id,chat_count) values(cid,1) on conflict(character_id) do update set chat_count=char_stats.chat_count+1 $$;
create function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,name) values(new.id,split_part(new.email,'@',1)); return new; end $$;
create trigger on_signup after insert on auth.users for each row execute function handle_new_user();
